import{_ as o,a0 as s,w as r,s as p,ao as l,I as a,x as n,a1 as u,A as e}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const N=JSON.parse(`{"title":"Ubuntu Unity 4歲了，生日快樂！ | LCTT x X-CMD","titleTemplate":false,"description":"Ubuntu Unity 4歲了，生日快樂！ | LCTT (201410) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Ubuntu Unity 4歲了，生日快樂！ | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Ubuntu Unity 4歲了，生日快樂！ | LCTT (201410) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201410/20141013 Ubuntu's Unity Turns 4 Happy Birthday","title":"Ubuntu Unity 4歲了，生日快樂！","tag":"201410","desc":""},"relativePath":"201410/20141013 Ubuntu's Unity Turns 4 Happy Birthday.md","filePath":"[post].md"}`),U={name:"201410/20141013 Ubuntu's Unity Turns 4 Happy Birthday.md"};function y(b,t,d,m,T,f){const i=s("Link");return r(),p("div",null,[t[13]||(t[13]=l('<h1 id="ubuntu-unity-4歲了-生日快樂" tabindex="-1">Ubuntu Unity 4歲了，生日快樂！ <a class="header-anchor" href="#ubuntu-unity-4歲了-生日快樂" aria-label="Permalink to “Ubuntu Unity 4歲了，生日快樂！”">​</a></h1><blockquote><p>Unity桌面環境在Ubuntu 10.04 Netbook Remix版本中加入，這是一個過期的舊版本。</p></blockquote><p><strong>Canonical開發者以及Ubuntu社區這些天有一個很好的理由來慶祝，因為Unity桌面環境已經4歲了</strong></p><p>Unity 作為Ubuntu的默認桌面環境，並且已經有4年了，雖然當時並不是該發行版的桌面版本。它首次用於Ubuntu Netbook Remix，是專為筆記本使用的版本。實際上Ubuntu Netbook Remix 10.10 Maverick市場首次接受Unity桌面。</p><p>常規的Ubuntu 10.10 發行版桌面仍舊使用GNOME 2.x，這也是為什麼有用户説10.10 仍是Canonical做的最好的版本。</p><h3 id="unity-是沒人想要的替代品" tabindex="-1">Unity 是沒人想要的替代品 <a class="header-anchor" href="#unity-是沒人想要的替代品" aria-label="Permalink to “Unity 是沒人想要的替代品”">​</a></h3><p>Canonical決定用他們自己的軟件替代GNOME 2.x桌面環境，但是它的設計對用户而言很陌生。一些人喜歡它，但是許多人並不這樣認為，並且還被不同的用户在他們決定放棄Ubuntu的時候時不時地提到這個。</p><p>Unit設計視角上和GNOME不同，但是Ubuntu開發者並沒有替換GNOME所有的包，並且還保留了很多（他們現在仍舊這樣）。之前不喜歡Unity方向的Ubuntu的粉絲一定對GNOME 2.x被很快拋棄，且被完全不同的、同樣引發相同質疑的GNOME 3.0替換感到很失望。</p><h3 id="為什麼unity替換gnome" tabindex="-1">為什麼Unity替換GNOME <a class="header-anchor" href="#為什麼unity替換gnome" aria-label="Permalink to “為什麼Unity替換GNOME”">​</a></h3><p>回到還在Ubuntu 10.10 的時光，Canonical和GNOME團隊習慣於非常緊密地一起工作，但是事情在Ubuntu變得越來越流行後發生了改變。其中一個驅使Canonical構建Unity的理由是GNOME團隊不再和他們一致了。</p><p>用户在抱怨GNOME的問題或者他們想要特定的功能時，Ubuntu團隊會發給上游一些補丁。對於GNOME，它會不會接受或者會花很長的時間去實現。在同時，Canonical和Ubuntu因這些他們不能馬上解決的問題受到了很多的批評，但是用户並不知道這些。</p><p>因此，一個與GNOME捆綁不太緊的桌面環境的需求變得非常清晰了。Unity最終在Ubuntu 11.10中引入。官方的發佈日期是 2010年10月10日，所以Unity已經4歲了。</p><p>Unity還沒有被全社區的擁抱，雖然有很多用户已經接受了這是一個有用、且可以作為一個生產桌面環境。雖然桌面的大修已經逾期了很久且勢必會在一兩年內完成，但是它在每個新的發行後都會獲得了更多的支持和使用。</p><hr>',14)),a("p",null,[t[1]||(t[1]=n("via: ",-1)),u(i,{href:"http://news.softpedia.com/news/Ubuntu-s-Unity-Turns-4-Happy-Birthday--461840.shtml"},{default:e(()=>[...t[0]||(t[0]=[n("http://news.softpedia.com/news/Ubuntu-s-Unity-Turns-4-Happy-Birthday--461840.shtml",-1)])]),_:1})]),a("p",null,[t[5]||(t[5]=n("作者：",-1)),u(i,{href:"http://news.softpedia.com/editors/browse/silviu-stahie"},{default:e(()=>[...t[2]||(t[2]=[n("Silviu Stahie",-1)])]),_:1}),t[6]||(t[6]=n(" 譯者：",-1)),u(i,{href:"https://github.com/geekpi"},{default:e(()=>[...t[3]||(t[3]=[n("geekpi",-1)])]),_:1}),t[7]||(t[7]=n(" 校對：",-1)),u(i,{href:"https://github.com/wxy"},{default:e(()=>[...t[4]||(t[4]=[n("wxy",-1)])]),_:1})]),a("p",null,[t[10]||(t[10]=n("本文由 ",-1)),u(i,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...t[8]||(t[8]=[n("LCTT",-1)])]),_:1}),t[11]||(t[11]=n(" 原創翻譯，",-1)),u(i,{href:"http://linux.cn/"},{default:e(()=>[...t[9]||(t[9]=[n("Linux中國",-1)])]),_:1}),t[12]||(t[12]=n(" 榮譽推出",-1))])])}const h=o(U,[["render",y]]);export{N as __pageData,h as default};
